import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import PropTypes from 'prop-types';

/**
 * GarageNavbar - Navbar หลักสำหรับหน้าอู่ซ่อม
 * แสดง: โลโก้ + ข้อมูลอู่ + การแจ้งเตือน + ข้อมูลผู้ใช้
 * 
 * Props:
 * - user: object - ข้อมูลผู้ใช้
 * - garage: object - ข้อมูลอู่
 * - onToggleSidebar: function - ฟังก์ชันสำหรับย่อ/ขยาย sidebar
 */
const GarageNavbar = ({ user, garage, onToggleSidebar }) => {
  const [showNotifications, setShowNotifications] = useState(false);
  const [showUserMenu, setShowUserMenu] = useState(false);

  // TODO: Backend - Logout
  const handleLogout = () => {
    console.log("Logout - TODO: Implement Backend");
    // localStorage.removeItem('token');
    // navigate('/login');
  };

  // TODO: Backend - ดึงการแจ้งเตือน
  // GET /api/garage/notifications
  const notifications = [
    { id: 1, type: 'new', message: 'ลูกค้าใหม่เลือกอู่ของคุณ - CLM-2024-008', time: '5 นาทีที่แล้ว', read: false },
    { id: 2, type: 'approval', message: 'บริษัทอนุมัติรายการเพิ่มเติม - CLM-2024-005', time: '1 ชั่วโมงที่แล้ว', read: false },
    { id: 3, type: 'info', message: 'อะไหล่สำหรับ CLM-2024-003 พร้อมส่ง', time: '3 ชั่วโมงที่แล้ว', read: true },
  ];

  const unreadCount = notifications.filter(n => !n.read).length;

  return (
    <nav className="bg-white shadow-md sticky top-0 z-40 animate-slide-down">
      <div className="container-custom">
        <div className="flex items-center justify-between h-16">
          
          {/* Left - Logo & Garage Info with Toggle Button */}
          <div className="flex items-center gap-3">
            {/* Toggle Sidebar Button */}
            <button
              onClick={onToggleSidebar}
              className="p-2 hover:bg-neutral-100 rounded-lg transition-colors duration-300"
              title="ย่อ/ขยาย เมนู"
            >
              <span className="material-icons-round text-neutral-600">menu</span>
            </button>

            {/* Logo */}
            <Link to="/garage/dashboard" className="flex items-center gap-3 group">
              <div className="w-10 h-10 bg-gradient-to-br from-orange-500 to-red-500 rounded-xl flex items-center justify-center shadow-button group-hover:shadow-glow-primary transition-all duration-300 group-hover:scale-110">
                <span className="material-icons-round text-white text-2xl">build</span>
              </div>
              <div>
                <h1 className="text-xl font-bold text-gradient-primary">ClaimMate</h1>
                <p className="text-xs text-neutral-500">{garage?.name || 'อู่ซ่อมรถยนต์'}</p>
              </div>
            </Link>
          </div>

          {/* Right Menu */}
          <div className="flex items-center gap-4">
            {/* Quick Stats */}
            <div className="hidden md:flex items-center gap-4 px-4 py-2 bg-neutral-50 rounded-lg">
              <div className="flex items-center gap-2">
                <span className="material-icons-round text-orange-500 text-sm">build</span>
                <div className="text-left">
                  <p className="text-xs text-neutral-500">กำลังซ่อม</p>
                  <p className="text-sm font-semibold text-neutral-dark">5</p>
                </div>
              </div>
              <div className="w-px h-8 bg-neutral-200"></div>
              <div className="flex items-center gap-2">
                <span className="material-icons-round text-green-500 text-sm">schedule</span>
                <div className="text-left">
                  <p className="text-xs text-neutral-500">รอดำเนินการ</p>
                  <p className="text-sm font-semibold text-neutral-dark">3</p>
                </div>
              </div>
            </div>

            {/* Notifications */}
            <div className="relative">
              <button
                onClick={() => setShowNotifications(!showNotifications)}
                className="relative p-2 text-neutral-600 hover:bg-neutral-100 rounded-lg transition-colors duration-300"
              >
                <span className="material-icons-round">notifications</span>
                {unreadCount > 0 && (
                  <span className="absolute top-1 right-1 w-5 h-5 bg-error text-white text-xs font-bold rounded-full flex items-center justify-center animate-bounce">
                    {unreadCount}
                  </span>
                )}
              </button>

              {/* Notifications Dropdown */}
              {showNotifications && (
                <>
                  <div 
                    className="fixed inset-0 z-30" 
                    onClick={() => setShowNotifications(false)}
                  ></div>
                  <div className="absolute right-0 mt-2 w-96 bg-white rounded-xl shadow-card-hover border border-neutral-200 overflow-hidden z-40 animate-scale-in">
                    <div className="p-4 border-b border-neutral-200 flex items-center justify-between">
                      <h3 className="font-semibold text-neutral-dark">การแจ้งเตือน</h3>
                      {unreadCount > 0 && (
                        <span className="text-xs text-primary-600 font-medium">
                          {unreadCount} ใหม่
                        </span>
                      )}
                    </div>
                    <div className="max-h-96 overflow-y-auto custom-scrollbar">
                      {notifications.map(notif => (
                        <div
                          key={notif.id}
                          className={`
                            p-4 border-b border-neutral-100 hover:bg-neutral-50 cursor-pointer transition-colors duration-200
                            ${!notif.read ? 'bg-blue-50/50' : ''}
                          `}
                        >
                          <div className="flex items-start gap-3">
                            <span className={`
                              material-icons-round text-xl
                              ${notif.type === 'new' ? 'text-orange-500' : 
                                notif.type === 'approval' ? 'text-green-500' : 'text-info'}
                            `}>
                              {notif.type === 'new' ? 'new_releases' : 
                               notif.type === 'approval' ? 'check_circle' : 'info'}
                            </span>
                            <div className="flex-1">
                              <p className="text-sm text-neutral-dark">{notif.message}</p>
                              <p className="text-xs text-neutral-400 mt-1">{notif.time}</p>
                            </div>
                            {!notif.read && (
                              <div className="w-2 h-2 bg-primary-500 rounded-full"></div>
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                    <Link
                      to="/garage/notifications"
                      className="block p-3 text-center text-sm text-primary-600 hover:bg-neutral-50 font-medium"
                    >
                      ดูทั้งหมด
                    </Link>
                  </div>
                </>
              )}
            </div>

            {/* User Menu */}
            <div className="relative">
              <button
                onClick={() => setShowUserMenu(!showUserMenu)}
                className="flex items-center gap-3 p-2 hover:bg-neutral-50 rounded-lg transition-colors duration-300"
              >
                <div className="w-10 h-10 bg-gradient-to-br from-orange-500 to-red-500 rounded-full flex items-center justify-center text-white font-semibold">
                  {user?.avatar ? (
                    <img src={user.avatar} alt={user.name} className="w-full h-full rounded-full object-cover" />
                  ) : (
                    <span>{user?.name?.charAt(0) || 'U'}</span>
                  )}
                </div>
                <div className="text-left hidden md:block">
                  <p className="text-sm font-medium text-neutral-dark">{user?.name || 'ผู้ใช้'}</p>
                  <p className="text-xs text-neutral-500">{user?.position || 'ช่าง'}</p>
                </div>
                <span className="material-icons-round text-neutral-400">expand_more</span>
              </button>

              {/* User Dropdown */}
              {showUserMenu && (
                <>
                  <div 
                    className="fixed inset-0 z-30" 
                    onClick={() => setShowUserMenu(false)}
                  ></div>
                  <div className="absolute right-0 mt-2 w-64 bg-white rounded-xl shadow-card-hover border border-neutral-200 overflow-hidden z-40 animate-scale-in">
                    <div className="p-4 border-b border-neutral-200">
                      <p className="font-semibold text-neutral-dark">{user?.name || 'ผู้ใช้'}</p>
                      <p className="text-sm text-neutral-500">{user?.email || 'user@example.com'}</p>
                      <p className="text-xs text-neutral-400 mt-1">{user?.position || 'ช่าง'}</p>
                    </div>
                    <div className="py-2">
                      <Link
                        to="/garage/profile"
                        className="flex items-center gap-3 px-4 py-3 hover:bg-neutral-50 transition-colors duration-200"
                      >
                        <span className="material-icons-round text-neutral-400">person</span>
                        <span className="text-sm text-neutral-dark">โปรไฟล์</span>
                      </Link>
                      <Link
                        to="/garage/settings"
                        className="flex items-center gap-3 px-4 py-3 hover:bg-neutral-50 transition-colors duration-200"
                      >
                        <span className="material-icons-round text-neutral-400">settings</span>
                        <span className="text-sm text-neutral-dark">ตั้งค่า</span>
                      </Link>
                    </div>
                    <div className="border-t border-neutral-200 py-2">
                      <button
                        onClick={handleLogout}
                        className="flex items-center gap-3 px-4 py-3 hover:bg-red-50 transition-colors duration-200 w-full text-left"
                      >
                        <span className="material-icons-round text-error">logout</span>
                        <span className="text-sm text-error">ออกจากระบบ</span>
                      </button>
                    </div>
                  </div>
                </>
              )}
            </div>
          </div>
        </div>
      </div>
    </nav>
  );
};

GarageNavbar.propTypes = {
  user: PropTypes.shape({
    id: PropTypes.string,
    name: PropTypes.string,
    email: PropTypes.string,
    position: PropTypes.string,
    avatar: PropTypes.string,
  }),
  garage: PropTypes.shape({
    id: PropTypes.string,
    name: PropTypes.string,
    phone: PropTypes.string,
    address: PropTypes.string,
  }),
  onToggleSidebar: PropTypes.func,
};

GarageNavbar.defaultProps = {
  onToggleSidebar: () => {},
};

export default GarageNavbar;
